@CrossOrigin
@RestController
@RequestMapping("/ClaimQuery")
public class ClaimQueryRestController extends BaseSpringRestController {
	
	public ClaimQueryRestController( ClaimService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Claim using a UUID
     * @param		UUID claimId
     * @return		Claim
     */    
    @GetMapping("/load")
    public Claim load( @RequestParam(required=true) UUID claimId ) {
    	Claim entity = null;

    	try {  
    		entity = service.getClaim( new ClaimFetchOneSummary( claimId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Claim using Id " + claimId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Claim business objects
     * @return		Set<Claim>
     */
    @GetMapping("/")
    public List<Claim> loadAll() {                
    	List<Claim> claimList = null;
        
    	try {
            // load the Claim
            claimList = service.getAllClaim();
            
            if ( claimList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Claims" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Claims ", exc );
        	return null;
        }

        return claimList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Claim claim = null;
    protected ClaimService service = null;
    private static final Logger LOGGER = Logger.getLogger(ClaimQueryRestController.class.getName());
    
}
